/**
 * Creates the quotation for one custom request together with its first `DRAFT` version and the priced lines that explain it. The two commit together: there is no quotation without its first version. A request may hold exactly one quotation — a later price is a new **version** of it, not a second quotation.
 *
 * Only the lines, the shipping fee and an optional adjustment are priced input. The line totals, the subtotal, the total and the deposit/remaining split are all derived: the split comes from published business policy, not from this request, and the amounts are exact decimal throughout — send them as strings.
 *
 * This drafts only. The customer is not told, nothing is sent, no validity window starts and the request itself does not move.
 * @summary Create the quotation for a request with its first draft version
 */
export const adminQuotationCreate = (
  createQuotationDraftBody: CreateQuotationDraftBody,
  options?: SecondParameter<typeof apiRequest<AdminQuotationCreate201>>,
) => {
  return apiRequest<AdminQuotationCreate201>(
    {
      url: `/api/admin/quotations`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: createQuotationDraftBody,
    },
    options,
  );
};

/**
 * The complete version history, oldest first by version number — the order the database assigned them in, consecutively and without reuse. It is not paginated and nothing is filtered out: a superseded, expired or rejected version stays in the history exactly as it was priced.
 *
 * Each entry carries that version’s **own** recorded facts — its amounts, the deposit share it was priced at, its adjustment and the reason for it, and the timestamps it actually reached. Nothing is recalculated and nothing is re-derived from current business policy, so a version drafted under an older deposit split still reads as that split. Amounts are exact decimal strings.
 *
 * This is a read. It sends nothing, moves no version, advances no pointer and does not expire an offer whose validity has lapsed.
 * @summary List every version of one quotation
 */
export const adminQuotationVersionHistory = (
  quotationId: unknown,
  options?: SecondParameter<typeof apiRequest<AdminQuotationVersionHistory200>>,
) => {
  return apiRequest<AdminQuotationVersionHistory200>(
    { url: `/api/admin/quotations/${quotationId}/versions`, method: 'GET' },
    options,
  );
};

/**
 * Re-prices a quotation by adding the next `DRAFT` version with its own priced lines. It is an append: earlier versions — including any that were already sent — are left exactly as they are and stay readable, and there is no route anywhere that edits one. Version numbers are assigned by the server, consecutively, and are never reused.
 *
 * The deposit split is read from published policy again for this version, so a version prices under the policy in force when it is drafted.
 *
 * This drafts only: it sends nothing, starts no validity window and does not move the custom request.
 * @summary Add a further draft version to an existing quotation
 */
export const adminQuotationAddVersion = (
  quotationId: unknown,
  addQuotationVersionBody: AddQuotationVersionBody,
  options?: SecondParameter<typeof apiRequest<AdminQuotationAddVersion201>>,
) => {
  return apiRequest<AdminQuotationAddVersion201>(
    {
      url: `/api/admin/quotations/${quotationId}/versions`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: addQuotationVersionBody,
    },
    options,
  );
};

/**
 * Returns the version named by `versionId` — **that** version, never the current or the latest one — together with its own frozen lines, ordered by position. A version belonging to a different quotation is not readable through this path: it answers `QUOTATION_VERSION_NOT_FOUND`, the same answer a version that does not exist gets.
 *
 * Every figure is the one recorded when the version was drafted: the line totals, the subtotal, the adjustment and its reason, the total, and the deposit split with the percentage it was priced at. None of it is recomputed and none of it is re-read from today’s policy, which is what makes an older version explainable rather than merely present. Amounts are exact decimal strings.
 *
 * This is a read, with no effect on the version, the quotation or the request.
 * @summary Read one exact quotation version with its priced lines
 */
export const adminQuotationVersionDetail = (
  quotationId: unknown,
  versionId: unknown,
  options?: SecondParameter<typeof apiRequest<AdminQuotationVersionDetail200>>,
) => {
  return apiRequest<AdminQuotationVersionDetail200>(
    { url: `/api/admin/quotations/${quotationId}/versions/${versionId}`, method: 'GET' },
    options,
  );
};

/**
 * Freezes the version named by `versionId` — **that** version, never the latest one — and makes it the price the customer is looking at. One transaction does all of it: the version becomes `SENT` with its validity window, any previously sent version becomes `SUPERSEDED`, the quotation points at this version, the request points at this quotation, and the request moves to `QUOTED` when it was under review. Nothing partial survives a failure.
 *
 * Nothing is re-priced. The lines, the subtotal, the total and the deposit split are the ones the version was drafted with; the send adds `sentAt`, `validFrom` and `validUntil` and touches no amount. The validity window comes from published business policy, not from this request — there is no body, and the operator supplies nothing but the two identifiers in the path.
 *
 * Sending the same version twice is safe and is the intended way to re-issue it: the second call replays, returning the committed result without re-freezing it, moving a date, changing a pointer or notifying the customer again. A version that has been superseded, accepted, rejected, expired or voided cannot be sent — draft a new version instead.
 * @summary Send one exact quotation version to the customer
 */
export const adminQuotationSendVersion = (
  quotationId: unknown,
  versionId: unknown,
  options?: SecondParameter<typeof apiRequest<AdminQuotationSendVersion200>>,
) => {
  return apiRequest<AdminQuotationSendVersion200>(
    { url: `/api/admin/quotations/${quotationId}/versions/${versionId}/send`, method: 'POST' },
    options,
  );
};

